package com.caroadmap;

import com.caroadmap.data.RewardTier;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup("CARoadmap")
public interface CARoadmapConfig extends Config
{
	@ConfigItem(
		keyName = "targetRewardTier",
		name = "Target reward tier",
		description = "The Combat Achievement reward tier you're working towards. "
			+ "Recommendations aim to close the point gap to this tier's threshold."
	)
	default RewardTier targetRewardTier()
	{
		return RewardTier.GRANDMASTER;
	}
}

package com.caroadmap.ui;

import com.caroadmap.CombatSession;
import com.caroadmap.data.Task;
import com.caroadmap.data.TaskType;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

import javax.swing.*;
import java.awt.*;
import java.util.Comparator;
import java.util.List;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import java.util.stream.Collectors;

public class StaminaCombatSection extends JPanel
{
    private static final Pattern STREAK_PATTERN =
            Pattern.compile("(\\d+)\\s+times?\\s+without",
                    Pattern.CASE_INSENSITIVE);

    private final JLabel taskLabel = new JLabel();

    private final JProgressBar progressBar =
            new JProgressBar();

    public StaminaCombatSection()
    {
        setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
        setBackground(ColorScheme.DARK_GRAY_COLOR);

        JLabel title = new JLabel("Stamina Tasks");
        title.setFont(FontManager.getRunescapeBoldFont());
        title.setAlignmentX(Component.CENTER_ALIGNMENT);

        taskLabel.setFont(FontManager.getRunescapeSmallFont());
        taskLabel.setAlignmentX(Component.CENTER_ALIGNMENT);

        progressBar.setMaximum(100);
        progressBar.setStringPainted(true);
        progressBar.setAlignmentX(Component.CENTER_ALIGNMENT);

        add(title);
        add(Box.createRigidArea(new Dimension(0, 5)));
        add(taskLabel);
        add(Box.createRigidArea(new Dimension(0, 5)));
        add(progressBar);
    }

    public void update(CombatSession session)
    {
        renderProgress(session);
    }

    private void renderProgress(CombatSession session)
    {
        taskLabel.setText("");

        if (session.getTasks() == null)
        {
            setVisible(false);
            return;
        }

        List<Task> staminaTasks =
                session.getTasks()
                        .stream()
                        .filter(t -> t.getType() == TaskType.STAMINA)
                        .collect(Collectors.toList());

        if (staminaTasks.isEmpty())
        {
            setVisible(false);
            return;
        }

        Task nextTask =
                staminaTasks.stream()
                        .filter(t -> getRequiredStreak(t) != null)
                        .filter(t ->
                                session.getKillStreak() < getRequiredStreak(t))
                        .min(Comparator.comparingInt(this::getRequiredStreak))
                        .orElse(null);

        // Player has completed every stamina task.
        if (nextTask == null)
        {
            setVisible(false);
            return;
        }

        setVisible(true);

        int required = getRequiredStreak(nextTask);
        int current = session.getKillStreak();

        double ratio = (double) current / required;

        progressBar.setValue(
                (int) (Math.min(ratio, 1.0) * 100)
        );

        progressBar.setString(
                String.format("%d / %d", current, required)
        );

        taskLabel.setText(nextTask.getTaskName());

        if (!session.isStreakValid())
        {
            progressBar.setValue(0);
            progressBar.setString("Streak Broken");
        }

        revalidate();
        repaint();
    }

    private Integer getRequiredStreak(Task task)
    {
        Matcher matcher =
                STREAK_PATTERN.matcher(task.getTaskDescription());

        if (!matcher.find())
        {
            return null;
        }

        return Integer.parseInt(matcher.group(1));
    }
}

package com.caroadmap.ui;

import com.caroadmap.CombatSession;
import com.caroadmap.data.Task;
import com.caroadmap.data.TaskType;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

import javax.swing.*;
import java.awt.*;
import java.util.Comparator;
import java.util.List;
import java.util.stream.Collectors;

public class KillCountCombatSection extends JPanel {
    private final JLabel taskLabel = new JLabel();

    private final JProgressBar progressBar =
            new JProgressBar();


    public KillCountCombatSection()
    {
        setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
        setBackground(ColorScheme.DARK_GRAY_COLOR);

        JLabel titleLabel = new JLabel("Kill Count Tasks");
        titleLabel.setFont(FontManager.getRunescapeBoldFont());
        titleLabel.setAlignmentX(Component.CENTER_ALIGNMENT);


        taskLabel.setFont(
                FontManager.getRunescapeSmallFont()
        );
        taskLabel.setAlignmentX(Component.CENTER_ALIGNMENT);


        progressBar.setStringPainted(true);
        progressBar.setMaximum(100);
        progressBar.setAlignmentX(Component.CENTER_ALIGNMENT);
        progressBar.setPreferredSize(
                new Dimension(200, 20)
        );


        add(titleLabel);
        add(Box.createRigidArea(new Dimension(0, 5)));
        add(taskLabel);
        add(Box.createRigidArea(new Dimension(0, 5)));
        add(progressBar);
    }


    public void update(CombatSession session)
    {
        renderProgress(session);
    }


    private void renderProgress(CombatSession session)
    {
        if (session.getTasks() == null)
        {
            return;
        }


        List<Task> killTasks =
                session.getTasks()
                        .stream()
                        .filter(t ->
                                t.getType() == TaskType.KILL_COUNT
                        )
                        .collect(Collectors.toList());


        if (killTasks.isEmpty())
        {
            setVisible(false);
            return;
        }


        setVisible(true);


        Task closestTask =
                killTasks.stream()
                        .min(
                                Comparator.comparingDouble(
                                        Task::getKillProgressRatio
                                )
                        )
                        .orElse(null);


        if (closestTask == null)
        {
            return;
        }


        double progress =
                closestTask.getKillProgressRatio() * 100;


        progressBar.setValue(
                (int) progress
        );


        progressBar.setString(
                String.format(
                        "%.0f%% (%d / %d)",
                        progress,
                        closestTask.getCurrentKills().intValue(),
                        closestTask.getRequiredKills().intValue()
                )
        );


        taskLabel.setText(
                closestTask.getTaskName()
        );


        revalidate();
        repaint();
    }
}

package com.caroadmap.ui;

import com.caroadmap.data.Task;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.game.SpriteManager;
import net.runelite.client.hiscore.HiscoreSkill;
import net.runelite.client.util.ImageUtil;

import javax.swing.*;
import java.awt.image.BufferedImage;
import java.util.Arrays;
import java.util.Map;

import static net.runelite.api.SpriteID.TAB_COMBAT;

@Slf4j
public class BossIconUtil {
    private static final Map<String, HiscoreSkill> HISCORE_ALIASES = Map.ofEntries(
            Map.entry("theatre of blood", HiscoreSkill.THEATRE_OF_BLOOD),
            Map.entry("theatre of blood entry mode", HiscoreSkill.THEATRE_OF_BLOOD),
            Map.entry("theatre of blood hard mode", HiscoreSkill.THEATRE_OF_BLOOD),

            Map.entry("chambers of xeric", HiscoreSkill.CHAMBERS_OF_XERIC),
            Map.entry("chambers of xeric challenge mode", HiscoreSkill.CHAMBERS_OF_XERIC),

            Map.entry("tombs of amascut", HiscoreSkill.TOMBS_OF_AMASCUT),
            Map.entry("tombs of amascut expert mode", HiscoreSkill.TOMBS_OF_AMASCUT_EXPERT),

            Map.entry("barrows", HiscoreSkill.BARROWS_CHESTS),
            Map.entry("moons of peril", HiscoreSkill.LUNAR_CHESTS),
            Map.entry("crystalline hunllef", HiscoreSkill.THE_GAUNTLET),
            Map.entry("corrupted hunllef", HiscoreSkill.THE_CORRUPTED_GAUNTLET),
            Map.entry("fortis colosseum", HiscoreSkill.SOL_HEREDIT),
            Map.entry("tzhaar ket raks challenges", HiscoreSkill.TZTOK_JAD),
            Map.entry("royal titans", HiscoreSkill.THE_ROYAL_TITANS),
            Map.entry("the nightmare", HiscoreSkill.NIGHTMARE)
    );


    protected static JLabel createBossIcon(String bossName, SpriteManager spriteManager)
    {
        JLabel icon = new JLabel();

        HiscoreSkill skill = getBossSkill(bossName);

        if (skill == null)
        {
            log.debug("Could not find {} hiscore sprite", bossName);
        }

        spriteManager.getSpriteAsync(
                skill == null ? TAB_COMBAT : skill.getSpriteId(),
                0,
                sprite -> SwingUtilities.invokeLater(() ->
                {
                    BufferedImage scaled =
                            ImageUtil.resizeImage(
                                    ImageUtil.resizeCanvas(sprite, 25, 25),
                                    20,
                                    20);

                    icon.setIcon(new ImageIcon(scaled));
                }));

        return icon;
    }

    public static void loadBossIcon(
            String bossName,
            SpriteManager spriteManager,
            JLabel label)
    {
        HiscoreSkill skill = getBossSkill(bossName);

        if (skill == null)
        {
            log.debug("Could not find {} hiscore sprite", bossName);
        }

        spriteManager.getSpriteAsync(
                skill == null ? TAB_COMBAT : skill.getSpriteId(),
                0,
                sprite -> SwingUtilities.invokeLater(() ->
                {
                    BufferedImage scaled =
                            ImageUtil.resizeImage(
                                    ImageUtil.resizeCanvas(sprite, 25, 25),
                                    20,
                                    20);

                    label.setIcon(new ImageIcon(scaled));
                }));
    }

    private static HiscoreSkill getBossSkill(String boss) {
        String normalized = BossNameUtil.normalizeBossName(boss);

        // Exact alias first
        HiscoreSkill alias = HISCORE_ALIASES.get(normalized);
        if (alias != null) {
            return alias;
        }

        // Try automatic enum lookup
        try {
            return HiscoreSkill.valueOf(
                    normalized
                            .toUpperCase()
                            .replace(" ", "_")
            );
        }
        catch (IllegalArgumentException ignored) {
        }

        // Try prepending THE_
        try {
            return HiscoreSkill.valueOf(
                    "THE_" + normalized
                            .toUpperCase()
                            .replace(" ", "_")
            );
        }
        catch (IllegalArgumentException ignored) {
        }

        // Try stripping suffixes
        String[] parts = normalized.split(" ");

        for (int i = parts.length - 1; i > 0; i--) {
            String candidate = String.join("_", Arrays.copyOf(parts, i))
                    .toUpperCase();

            try {
                return HiscoreSkill.valueOf(candidate);
            }
            catch (IllegalArgumentException ignored) {
            }

            try {
                return HiscoreSkill.valueOf("THE_" + candidate);
            }
            catch (IllegalArgumentException ignored) {
            }
        }

        return null;
    }
}

package com.caroadmap.ui;

import com.caroadmap.CombatSession;
import com.caroadmap.data.Task;
import com.caroadmap.data.TaskType;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

import javax.swing.*;
import java.awt.*;
import java.util.List;
import java.util.stream.Collectors;

public class SpeedCombatSection extends JPanel {
    private final JLabel timerLabel = new JLabel();
    private final JPanel targetsPanel = new JPanel();

    public SpeedCombatSection()
    {
        setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
        setBackground(ColorScheme.DARK_GRAY_COLOR);

        JLabel title = new JLabel("Speed Tasks");
        title.setFont(FontManager.getRunescapeBoldFont());
        title.setAlignmentX(Component.CENTER_ALIGNMENT);


        timerLabel.setFont(
                FontManager.getRunescapeBoldFont()
                        .deriveFont(28f)
        );
        timerLabel.setAlignmentX(Component.CENTER_ALIGNMENT);


        targetsPanel.setLayout(
                new BoxLayout(targetsPanel, BoxLayout.Y_AXIS)
        );
        targetsPanel.setAlignmentX(Component.CENTER_ALIGNMENT);


        add(title);
        add(Box.createRigidArea(new Dimension(0, 5)));
        add(timerLabel);
        add(Box.createRigidArea(new Dimension(0, 10)));
        add(targetsPanel);
    }


    public void update(CombatSession session)
    {
        renderTimer(session);
        renderTargets(session);
    }


    private void renderTimer(CombatSession session)
    {
        long elapsed = session.getElapsedSeconds();

        timerLabel.setText(
                formatTime(elapsed)
        );
    }


    private void renderTargets(CombatSession session)
    {
        targetsPanel.removeAll();

        if (session.getTasks() == null) {
            return;
        }


        List<Task> speedTasks =
                session.getTasks()
                        .stream()
                        .filter(t -> t.getType() == TaskType.SPEED)
                        .collect(Collectors.toList());


        for (Task task : speedTasks)
        {
            JLabel taskLabel = new JLabel(
                    formatTask(task, session)
            );

            taskLabel.setFont(
                    FontManager.getRunescapeSmallFont()
            );


            if (hasFailed(task, session))
            {
                taskLabel.setForeground(Color.RED);
            }
            else
            {
                taskLabel.setForeground(Color.GREEN);
            }


            targetsPanel.add(taskLabel);
        }


        targetsPanel.revalidate();
        targetsPanel.repaint();
    }


    private boolean hasFailed(Task task, CombatSession session)
    {
        return session.getElapsedSeconds()
                > task.getTargetTimeSeconds();
    }


    private String formatTime(long seconds)
    {
        return String.format(
                "%02d:%02d",
                seconds / 60,
                seconds % 60
        );
    }


    private String formatTask(Task task, CombatSession session)
    {
        long target =
                task.getTargetTimeSeconds().longValue();


        return String.format(
                "%s %s - %d:%02d",
                hasFailed(task, session)
                        ? "✗"
                        : "✓",
                task.getTaskName(),
                target / 60,
                target % 60
        );
    }
}

package com.caroadmap.ui;

import com.caroadmap.CARoadmapPlugin;
import com.caroadmap.CombatSession;
import com.caroadmap.CombatSessionManager;
import com.caroadmap.data.RecommendTasks;
import com.caroadmap.data.SortingType;
import com.caroadmap.data.Task;
import com.caroadmap.data.TaskType;
import lombok.Setter;
import lombok.extern.slf4j.Slf4j;

import net.runelite.client.config.ConfigManager;
import net.runelite.client.game.SpriteManager;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;
import net.runelite.client.util.ImageUtil;

import javax.inject.Inject;
import javax.swing.*;
import javax.swing.border.EmptyBorder;
import java.awt.*;
import java.awt.event.ActionEvent;
import java.awt.event.ActionListener;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.concurrent.ExecutorService;
import java.util.stream.Collectors;

@Slf4j
public class CARoadmapPanel extends PluginPanel{
    public enum PanelMode
    {
        RECOMMENDATIONS,
        COMBAT
    }

    @Setter
    private PanelMode panelMode = PanelMode.RECOMMENDATIONS;

    private final JPanel mainContainer = new JPanel(new CardLayout());

    private final JPanel recommendationView = new JPanel();
    private final JPanel combatView = new JPanel();

    private final CombatHeaderPanel combatHeaderPanel;

    // sections for combat view
    private final SpeedCombatSection speedCombatSection = new SpeedCombatSection();
    private final KillCountCombatSection killCountCombatSection = new KillCountCombatSection();
    private final StaminaCombatSection staminaCombatSection = new StaminaCombatSection();
    private final CombatChecklistSection combatCheckListSection = new CombatChecklistSection();

    private final JPanel recommendedContainer;
    private final JPanel completedContainer;

    @Setter
    private RecommendTasks recommendTasks;
    @Setter
    private Long characterId = null;
    private final ConfigManager configManager;
    private ArrayList<Task> recommendedList;
    private final Set<Task> completedList;
    private final SpriteManager spriteManager;
    private Boolean ascending;
    private SortingType sortingType;

    private final CombatSessionManager combatSessionManager;
    private final ExecutorService generalExecutor;

    @Inject
    public CARoadmapPanel(SpriteManager spriteManager, ConfigManager configManager, CombatSessionManager combatSessionManager, ExecutorService generalExecutor)
    {
        super(false);
        this.spriteManager = spriteManager;
        this.configManager = configManager;
        this.combatSessionManager = combatSessionManager;
        this.combatHeaderPanel = new CombatHeaderPanel(spriteManager);
        this.generalExecutor = generalExecutor;

        this.ascending = configManager.getConfiguration("CARoadmap", "isAscending", Boolean.class);
        if (this.ascending == null)
        {
            this.ascending = true;
            configManager.setConfiguration("CARoadmap", "isAscending", this.ascending);
        }

        this.sortingType = configManager.getConfiguration("CARoadmap", "sortingType", SortingType.class);
        if (this.sortingType == null)
        {
            this.sortingType = SortingType.SCORE;
            configManager.setConfiguration("CARoadmap", "sortingType", this.sortingType);
        }

        this.recommendedList = new ArrayList<>();
        this.completedList = new HashSet<>();

        // =========================
        // ROOT PANEL SETUP
        // =========================
        setLayout(new BorderLayout());
        setBackground(ColorScheme.DARK_GRAY_COLOR);
        setBorder(new EmptyBorder(5, 5, 5, 5));

        JLabel titleLabel = new JLabel("CA Roadmap");
        titleLabel.setFont(FontManager.getRunescapeBoldFont());

        // =========================
        // TOOLBAR (shared)
        // =========================
        JPanel tabBar = new JPanel();
        tabBar.setLayout(new FlowLayout(FlowLayout.LEFT));
        tabBar.setBackground(ColorScheme.DARKER_GRAY_COLOR);

        JButton recTab = new JButton("Recommendations");
        JButton combatTab = new JButton("Combat");

        recTab.addActionListener(e -> setMode(PanelMode.RECOMMENDATIONS));
        combatTab.addActionListener(e -> setMode(PanelMode.COMBAT));

        tabBar.add(recTab);
        tabBar.add(combatTab);

        JPanel toolbar = new JPanel();
        toolbar.setLayout(new BoxLayout(toolbar, BoxLayout.X_AXIS));
        toolbar.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        toolbar.setBorder(new EmptyBorder(5, 5, 5, 5));

        final BufferedImage refresh = ImageUtil.loadImageResource(CARoadmapPlugin.class, "/update_icon.png");
        final BufferedImage ascendingIcon = ImageUtil.loadImageResource(CARoadmapPlugin.class, "/a-z.png");
        final BufferedImage descendingIcon = ImageUtil.loadImageResource(CARoadmapPlugin.class, "/z-a.png");

        JComboBox<String> sortDropdown = getSortByMenu();
        JButton recommendationBtn = getRecommendationBtn(refresh);
        JButton sortingButton = getSortingButton(ascendingIcon, descendingIcon);

        toolbar.add(sortDropdown);
        toolbar.add(sortingButton);
        toolbar.add(recommendationBtn);

        // =========================
        // RECOMMENDATION VIEW
        // =========================
        recommendationView.setLayout(new BoxLayout(recommendationView, BoxLayout.Y_AXIS));
        recommendationView.setBackground(ColorScheme.DARK_GRAY_COLOR);

        JPanel recommendedTitlePanel = new JPanel(new FlowLayout(FlowLayout.LEFT, 0, 0));
        recommendedTitlePanel.setOpaque(false);

        JLabel recommendedTitle = new JLabel("Recommended: ");
        recommendedTitle.setFont(FontManager.getRunescapeBoldFont());
        recommendedTitlePanel.add(recommendedTitle);

        JPanel completedTitlePanel = new JPanel(new FlowLayout(FlowLayout.LEFT, 0, 0));
        completedTitlePanel.setOpaque(false);

        JLabel completedTitle = new JLabel("Completed: ");
        completedTitle.setFont(FontManager.getRunescapeBoldFont());
        completedTitlePanel.add(completedTitle);

        this.recommendedContainer = new JPanel();
        recommendedContainer.setLayout(new BoxLayout(recommendedContainer, BoxLayout.Y_AXIS));
        recommendedContainer.setBorder(new EmptyBorder(5, 5, 5, 5));

        this.completedContainer = new JPanel();
        completedContainer.setLayout(new BoxLayout(completedContainer, BoxLayout.Y_AXIS));
        completedContainer.setBorder(new EmptyBorder(5, 5, 5, 5));

        JScrollPane scrollPane = new JScrollPane(recommendedContainer);
        scrollPane.setHorizontalScrollBarPolicy(JScrollPane.HORIZONTAL_SCROLLBAR_NEVER);
        scrollPane.setPreferredSize(new Dimension(0, 300));

        JScrollPane completedScroll = new JScrollPane(completedContainer);
        completedScroll.setHorizontalScrollBarPolicy(JScrollPane.HORIZONTAL_SCROLLBAR_NEVER);
        completedScroll.setPreferredSize(new Dimension(0, 300));

        recommendationView.add(toolbar);
        recommendationView.add(Box.createRigidArea(new Dimension(0, 10)));
        recommendationView.add(recommendedTitlePanel);
        recommendationView.add(scrollPane);
        recommendationView.add(Box.createRigidArea(new Dimension(0, 10)));
        recommendationView.add(completedTitlePanel);
        recommendationView.add(completedScroll);

        // =========================
        // COMBAT VIEW
        // =========================
        combatView.setLayout(new BoxLayout(combatView, BoxLayout.Y_AXIS));
        combatView.setBackground(ColorScheme.DARK_GRAY_COLOR);

        combatView.add(combatHeaderPanel);

        combatView.add(Box.createRigidArea(new Dimension(0, 10)));

        combatView.add(speedCombatSection);

        combatView.add(Box.createRigidArea(new Dimension(0, 10)));

        combatView.add(killCountCombatSection);

        combatView.add(Box.createRigidArea(new Dimension(0, 10)));

        combatView.add(staminaCombatSection);

        combatView.add(Box.createRigidArea(new Dimension(0, 10)));

        combatView.add(combatCheckListSection);



        // =========================
        // CARD LAYOUT SWITCHER
        // =========================
        mainContainer.setLayout(new CardLayout());
        mainContainer.add(recommendationView, PanelMode.RECOMMENDATIONS.name());
        mainContainer.add(combatView, PanelMode.COMBAT.name());

        // =========================
        // ROOT ATTACH
        // =========================
        add(titleLabel, BorderLayout.NORTH);
        add(tabBar, BorderLayout.NORTH);
        add(mainContainer, BorderLayout.CENTER);

        setMode(PanelMode.RECOMMENDATIONS);
    }

    private JButton getSortingButton(BufferedImage ascendingIcon, BufferedImage descendingIcon) {
        JButton acnOrDsc = new JButton(new ImageIcon(ascending != null && ascending ? ascendingIcon : descendingIcon));
        acnOrDsc.setToolTipText(ascending ? "ascending" : "descending");
        acnOrDsc.addActionListener(new ActionListener() {
            @Override
            public void actionPerformed(ActionEvent e) {
                if (ascending == null) {
                    ascending = true;
                }
                ascending = !ascending;
                configManager.setConfiguration("CARoadmap", "isAscending", ascending);
                acnOrDsc.setIcon(ascending ? new ImageIcon(ascendingIcon) : new ImageIcon(descendingIcon));
                acnOrDsc.setToolTipText(ascending ? "ascending" : "descending");
                if (recommendTasks != null) {
                    recommendTasks.setAscending(ascending);
                }
                refresh();
            }
        });
        acnOrDsc.setPreferredSize(new Dimension(24, 24));
        return acnOrDsc;
    }

    private JButton getRecommendationBtn(BufferedImage refresh) {
        JButton recommendationBtn = new JButton(new ImageIcon(refresh));
        recommendationBtn.addActionListener(new ActionListener() {
            @Override
            public void actionPerformed(ActionEvent e) {
                if (characterId != null) {
                    generalExecutor.submit(() -> {
                        recommendTasks.getRecommendations(characterId);
                        SwingUtilities.invokeLater(() -> refresh());
                    });
                }
                else {
                    log.error("Could not fetch recommendations. You need to be logged in.");
                }
            }
        });
        recommendationBtn.setPreferredSize(new Dimension(24, 24));
        recommendationBtn.setToolTipText("Refresh Recommendations");
        return recommendationBtn;
    }

    private JComboBox<String> getSortByMenu() {
        String[] options = { "Recommended", "Tier", "Boss" };
        JComboBox<String> sortDropdown = new JComboBox<>(options);
        if (sortingType != null) {
            if (sortingType == SortingType.SCORE) {
                sortDropdown.setSelectedItem("Recommended");
            }
            else if (sortingType == SortingType.TIER) {
                sortDropdown.setSelectedItem("Tier");
            }
            else if (sortingType == SortingType.BOSS) {
                sortDropdown.setSelectedItem("Boss");
            }
        }
        sortDropdown.addActionListener(e -> {
            String selected = (String) sortDropdown.getSelectedItem();
            if (selected != null) {
                SortingType newType = selected.equals("Recommended")
                        ? SortingType.SCORE
                        : SortingType.valueOf(selected.toUpperCase());
                this.sortingType = newType;
                configManager.setConfiguration("CARoadmap", "sortingType", newType);
                if (recommendTasks != null) {
                    recommendTasks.setSortingType(newType);
                }
                refresh();
            }
        });
        sortDropdown.setMaximumSize(new Dimension(150, 25));
        sortDropdown.setPreferredSize(new Dimension(150, 25));
        sortDropdown.setFont(FontManager.getRunescapeSmallFont());

        return sortDropdown;
    }

    public void refresh() {
        if (recommendTasks == null) {
            return;
        }
        // Apply current sort settings, then copy so panel-side removals
        // (separateCompletedTasks / taskCompleted) don't mutate RecommendTasks' list.
        recommendTasks.resort();
        this.recommendedList = new ArrayList<>(recommendTasks.getRecommendedTasks());
        separateCompletedTasks();
        updateTaskDisplay();
    }

    public void refreshCombat()
    {
        CombatSession session = combatSessionManager.getCurrentSession();

        if (session == null)
        {
            return;
        }

        combatHeaderPanel.update(session);
        speedCombatSection.update(session);
        killCountCombatSection.update(session);
        staminaCombatSection.update(session);
        combatCheckListSection.update(session);
    }

    public void setMode(PanelMode mode)
    {
        this.panelMode = mode;

        CardLayout cl = (CardLayout) mainContainer.getLayout();
        cl.show(mainContainer, mode.name());

        log.info("Switching panel mode to {}", mode);

        revalidate();
        repaint();
    }

    public boolean taskCompleted(String taskName) {
        Task toRemove = null;
        for (Task task: recommendedList) {
            if (task.getTaskName().equals(taskName)) {
                task.setDone(true);
                toRemove = task;
                completedList.add(task);
            }
        }

        if (toRemove != null) {
            recommendedList.remove(toRemove);
            recommendTasks.updateRecommendations(characterId, taskName);
            return true;
        }

        return false;
    }

    public void separateCompletedTasks() {
        List<Task> completed = recommendedList.stream()
                .filter(Task::isDone)
                .collect(Collectors.toList());

        log.info(String.valueOf(recommendedList));

        recommendedList.removeAll(completed);
        completedList.addAll(completed);
    }

    public void updateTaskDisplay() {
        recommendedContainer.removeAll();
        completedContainer.removeAll();
        for (Task task : recommendedList) {
            addTaskToContainers(task, recommendedContainer);
        }
        for (Task task: completedList) {
            addTaskToContainers(task, completedContainer);
        }
        recommendedContainer.revalidate();
        recommendedContainer.repaint();
        completedContainer.revalidate();
        completedContainer.repaint();
    }

    private void addTaskToContainers(Task task, JPanel container) {
        if (task.getType() == TaskType.KILL_COUNT) {
            container.add(new KillCountDisplayTask(task, spriteManager));
            container.add(Box.createRigidArea(new Dimension(0, 5)));
        }
        else if (task.getType() == TaskType.SPEED) {
            container.add(new SpeedDisplayTask(task, spriteManager));
            container.add(Box.createRigidArea(new Dimension(0, 5)));
        }
        else {
            container.add(new DisplayTask(task, spriteManager));
            container.add(Box.createRigidArea(new Dimension(0, 5)));
        }
    }
}

package com.caroadmap.ui;

import com.caroadmap.CombatSession;
import com.caroadmap.data.Task;
import com.caroadmap.data.TaskType;
import net.runelite.client.ui.ColorScheme;
