    EASY(VarbitID.CA_THRESHOLD_EASY, "Easy"),
    MEDIUM(VarbitID.CA_THRESHOLD_MEDIUM, "Medium"),
    HARD(VarbitID.CA_THRESHOLD_HARD, "Hard"),
    ELITE(VarbitID.CA_THRESHOLD_ELITE, "Elite"),
    MASTER(VarbitID.CA_THRESHOLD_MASTER, "Master"),
    GRANDMASTER(VarbitID.CA_THRESHOLD_GRANDMASTER, "Grandmaster");

    private final int thresholdVarbitId;
    private final String displayName;

    RewardTier(int thresholdVarbitId, String displayName) {
        this.thresholdVarbitId = thresholdVarbitId;
        this.displayName = displayName;
    }

    public int getThresholdVarbitId() {
        return thresholdVarbitId;
    }

    /** Label shown in the RuneLite config dropdown. */
    @Override
    public String toString() {
        return displayName;
    }
}

package com.caroadmap.data;

import net.runelite.api.Client;
import net.runelite.api.gameval.VarbitID;

import java.util.EnumMap;
import java.util.Map;

/**
 * Reads the player's Combat Achievement points progress straight from the game
 * client via varbits.
 * <p>
 * Every method here reads a varbit, so they MUST be called on the client thread
 * (from a {@code GameTick}/event handler, or inside {@code ClientThread.invoke}).
 * The varbits are populated on login; if a threshold reads {@code 0} it has not
 * synced yet and the call should be retried on a later tick.
 */
public final class CombatAchievementProgress {

    private CombatAchievementProgress() {
    }

    /**
     * The player's current total Combat Achievement points (sum across every
     * completed task).
     */
    public static int getCurrentPoints(Client client) {
        return client.getVarbitValue(VarbitID.CA_POINTS);
    }

    /**
     * Points required to unlock the given reward tier. Returns {@code 0} if the
     * client has not synced the threshold yet.
     */
    public static int getThreshold(Client client, RewardTier tier) {
        return client.getVarbitValue(tier.getThresholdVarbitId());
    }

    /**
     * All six reward-tier thresholds, in unlock order.
     */
    public static Map<RewardTier, Integer> getAllThresholds(Client client) {
        Map<RewardTier, Integer> thresholds = new EnumMap<>(RewardTier.class);
        for (RewardTier tier : RewardTier.values()) {
            thresholds.put(tier, getThreshold(client, tier));
        }
        return thresholds;
    }

    /**
     * Points the player still needs to reach {@code tier}. {@code 0} once the
     * tier is reached (or if the threshold has not synced yet).
     */
    public static int pointsNeededFor(Client client, RewardTier tier) {
        int gap = getThreshold(client, tier) - getCurrentPoints(client);
        return Math.max(gap, 0);
    }

    /**
     * The highest reward tier the player has already unlocked, or {@code null}
     * if they have not reached Easy yet (or the thresholds have not synced).
     * {@code RewardTier.values()} is in ascending unlock order, so the last
     * match wins.
     */
    public static RewardTier getCompletedTier(Client client) {
        int points = getCurrentPoints(client);
        RewardTier completed = null;
        for (RewardTier tier : RewardTier.values()) {
            int threshold = getThreshold(client, tier);
            if (threshold > 0 && points >= threshold) {
                completed = tier;
            }
        }
        return completed;
    }
}

package com.caroadmap.data;

public enum SortingType {
    BOSS,
    SCORE,
    TIER
}

package com.caroadmap.data;

import com.caroadmap.api.CARoadmapServer;
import com.caroadmap.dto.GetRecommendationsResponse;
import com.caroadmap.dto.RecommendedTaskDTO;
import lombok.Getter;
import lombok.Setter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.config.ConfigManager;

import java.io.IOException;
import java.time.Instant;
import java.time.temporal.ChronoUnit;
import java.util.ArrayList;
import java.util.Objects;

@Slf4j
public class RecommendTasks {
    @Getter
    private ArrayList<Task> recommendedTasks;
    private final RecommendationCacheHandler cacheHandler;

    @Setter
    private SortingType sortingType = SortingType.SCORE;
    @Setter
    private Boolean ascending = true;

    /**
     * Point gap to the player's target reward tier, passed to the server knapsack.
     * {@code null} means the player is already at/past the target - the server
     * falls back to a hard cap of 20 recommendations.
     */
    @Getter
    @Setter
    private Integer pointsNeeded;

    private final CARoadmapServer server;

    public RecommendTasks(CARoadmapServer server, ConfigManager configManager, RecommendationCacheHandler cacheHandler, Integer pointsNeeded) {
        this.pointsNeeded = pointsNeeded;
        this.sortingType = configManager.getConfiguration("CARoadmap", "sortingType", SortingType.class);
        if (sortingType == null) {
            sortingType = SortingType.SCORE;
        }

        this.ascending = configManager.getConfiguration("CARoadmap", "isAscending", Boolean.class);
        if (ascending == null) {
            ascending = true;
        }

        this.recommendedTasks = new ArrayList<>();
        this.cacheHandler = cacheHandler;
        this.server = server;
    }

    public boolean isAscending() {
        return ascending;
    }

    /**
     * Gets the recommendations from the server OR locally. First it will be locally then from the server.
     * @param characterId the character id of the player
     */
    public void getRecommendations(long characterId) {
        log.info("get Recommendations was called");
        if (hasValidCache(characterId)) {
            recommendedTasks = loadCachedRecommendations(characterId);
            if (recommendedTasks.size() >= 20) {
                log.info("Using cached recommendations");
                return;
            }

            log.info("Cache only has {} recommendations. Fetching fresh recommendations", recommendedTasks.size());
        }
        fetchAndCacheRecommendationsFromServer(characterId);
    }

    public void updateRecommendations(long characterId, String taskName) {
        cacheHandler.removeRecommendation(characterId, taskName);
    }

    private ArrayList<Task> loadCachedRecommendations(long characterId) {

        RecommendationCache cache =
                cacheHandler.loadCache(characterId);

        if (cache == null) {
            return new ArrayList<>();
        }

        return convertRecommendations(cache);
    }

    private ArrayList<Task> convertRecommendations(
            RecommendationCache response
    ) {
        ArrayList<Task> tasks = new ArrayList<>();

        for (RecommendedTaskDTO dto : response.getRecommendedTasks())
        {
            try
            {
                tasks.add(TaskMapper.fromDTO(dto));
            }
            catch (Exception e)
            {
                log.error("Failed converting recommendation", e);
            }
        }

        sortRecommendations(tasks);

        return tasks;
    }

    private void fetchAndCacheRecommendationsFromServer(long characterId) {

        try {

            GetRecommendationsResponse response =
                    server.getRecommendations(characterId, pointsNeeded);


            if (response.getError() != null) {
                log.error(
                        "Server error: {}",
                        response.getError()
                );
                return;
            }


            RecommendationCache cache =
                    new RecommendationCache();

            cache.setCharacterId(characterId);
            cache.setGeneratedAt(
                    response.getGeneratedAt()
            );
            cache.setPointsNeeded(pointsNeeded);
            cache.setRecommendedTasks(
                    response.getRecommendedTasks()
            );


            cacheHandler.saveCache(characterId, cache);


            this.recommendedTasks =
                    convertRecommendations(cache);


        } catch(Exception e) {

            log.error(
                    "Could not fetch recommendations",
                    e
            );
        }
    }

    /** Re-sorts the current recommendation list in place using the active sort settings. */
    public void resort() {
        sortRecommendations(recommendedTasks);
    }

    private void sortRecommendations(ArrayList<Task> tasks) {
        if (sortingType == SortingType.SCORE) {
            tasks.sort(this.ascending ? Task.byScore() : Task.byScore().reversed());
        } else if (sortingType == SortingType.BOSS) {
            tasks.sort(this.ascending ? Task.byBoss() : Task.byBoss().reversed());
        } else if (sortingType == SortingType.TIER) {
            tasks.sort(this.ascending ? Task.byTier() : Task.byTier().reversed());
        }
    }

    private boolean hasValidCache(long characterId) {

        RecommendationCache cache =
                cacheHandler.loadCache(characterId);


        if (cache == null) {
            return false;
        }

        // Cache was built for a different point target; force a refetch.
        if (!Objects.equals(cache.getPointsNeeded(), pointsNeeded)) {
            log.info(
                    "Cached recommendations target {} points, need {}. Refetching.",
                    cache.getPointsNeeded(),
                    pointsNeeded
            );
            return false;
        }

        Instant generatedAt =
                Instant.parse(cache.getGeneratedAt());


        return generatedAt
                .plus(7, ChronoUnit.DAYS)
                .isAfter(Instant.now());
    }

}

package com.caroadmap.data;

import java.util.*;

public class PlayerDataDiffUtil {
    public static List<Map<String, Object>> filterChangedBosses(List<Object> newList, List<Object> cachedList) {
        Map<String, Map<String, Object>> client = extractBossMap(newList);
        Map<String, Map<String, Object>> cached = extractBossMap(cachedList);

        client.entrySet().removeIf(e ->
                Objects.equals(e.getValue(), cached.get(e.getKey()))
        );

        return new ArrayList<>(client.values());
    }

    public static List<Map<String, Object>> filterChangedTasks(List<Object> newList, List<Object> cachedList) {
        Map<String, Boolean> clientTasks = extractTaskMap(newList);
        Map<String, Boolean> cachedTasks = extractTaskMap(cachedList);

        clientTasks.entrySet().removeIf(e -> Objects.equals(e.getValue(), cachedTasks.get(e.getKey())));

        List<Map<String, Object>> result = new ArrayList<>();
        for (Map.Entry<String, Boolean> e : clientTasks.entrySet()) {
            Map<String, Object> taskMap = new HashMap<>();
            taskMap.put("task_name", e.getKey());
            taskMap.put("Done", e.getValue());
            result.add(taskMap);
        }
        return result;
    }

    public static List<Map<String, Object>> filterChangedStats(List<Object> newList, List<Object> cachedList) {
        Map<String, Integer> clientStats = extractStatMap(newList);
        Map<String, Integer> cachedStats = extractStatMap(cachedList);

        clientStats.entrySet().removeIf(e -> Objects.equals(e.getValue(), cachedStats.get(e.getKey())));

        List<Map<String, Object>> result = new ArrayList<>();
        for (Map.Entry<String, Integer> e : clientStats.entrySet()) {
            Map<String, Object> statMap = new HashMap<>();
            statMap.put("skill_name", e.getKey());
            statMap.put("level", e.getValue());
            result.add(statMap);
        }
        return result;
    }

    private static Map<String, Boolean> extractTaskMap(List<Object> rawList) {
        Map<String, Boolean> map = new HashMap<>();
        for (Object obj : rawList) {
            if (obj instanceof Map) {
                Map<?, ?> m = (Map<?, ?>) obj;
                Object name = m.get("task_name");
                Object done = m.get("Done");
                if (name instanceof String && done instanceof Boolean) {
                    map.put((String) name, (Boolean) done);
                }
            }
        }
        return map;
    }

    private static Map<String, Integer> extractStatMap(List<Object> rawList) {
        Map<String, Integer> map = new HashMap<>();
        for (Object obj : rawList) {
            if (obj instanceof Map) {
                Map<?, ?> rawMap = (Map<?, ?>) obj;
                Object name = rawMap.get("skill_name");
                Object level = rawMap.get("level");
                if (name instanceof String && level instanceof Number) {
                    map.put((String) name, ((Number) level).intValue());
                }
            }
        }
        return map;
    }

    private static Map<String, Map<String, Object>> extractBossMap(List<Object> rawList) {
        Map<String, Map<String, Object>> map = new HashMap<>();

        for (Object obj : rawList) {
            if (obj instanceof Map) {
                Map<String, Object> boss = (Map<String, Object>) obj;
                map.put((String) boss.get("boss"), boss);
            }
        }

        return map;
    }

    public static List<Object> filterByKey(String key, List<Object> newVal, List<Object> cachedVal) {
        if ("boss_info".equals(key)) {
            return new ArrayList<Object>(filterChangedBosses(newVal, cachedVal));
        } else if ("tasks".equals(key)) {
            return new ArrayList<Object>(filterChangedTasks(newVal, cachedVal));
        } else if ("skills".equals(key)) {
            return new ArrayList<Object>(filterChangedStats(newVal, cachedVal));
        } else {
            return new ArrayList<Object>();
        }
    }
}

