package com.caroadmap;

import com.caroadmap.data.Task;
import com.caroadmap.data.TaskType;
import lombok.Getter;
import lombok.Setter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.NPC;

import java.util.HashSet;
import java.util.List;
import java.util.Set;

@Slf4j
public class CombatSession {
    @Getter
    private NPC boss;

    @Getter
    private String bossName;

    @Getter
    private boolean bossDefeated;

    @Getter
    private boolean streakValid = true;

    @Getter
    private int killStreak = 0;

    @Getter
    private final boolean instanced;

    @Getter
    @Setter
    private volatile List<Task> tasks;
    private final Set<String> failedTasks = new HashSet<>();

    private long startTime;
    private boolean active;
    private int idleTicks;

    private long finishTime;


    public CombatSession(NPC boss, boolean instanced)
    {
        this.boss = boss;
        this.bossName = boss.getName();
        this.startTime = System.currentTimeMillis();
        this.active = true;
        this.instanced = instanced;

        log.info("CombatSession created for {}", bossName);
    }

    public void updateBoss(NPC boss) {
        this.boss = boss;
    }

    public void updateKillCount(int killCount)
    {
        if (tasks == null)
        {
            return;
        }

        for (Task task : tasks)
        {
            if (task.getType() == TaskType.KILL_COUNT)
            {
                task.setCurrentKills((double) killCount);

                if (task.getRequiredKills() != null)
                {
                    double ratio =
                            killCount / task.getRequiredKills();

                    task.setKillProgressRatio(
                            Math.min(ratio, 1.0)
                    );

                    task.setKillsRemaining(
                            Math.max(
                                    task.getRequiredKills() - killCount,
                                    0
                            )
                    );
                }
            }
        }
    }

    public void failTask(String taskTitle)
    {
        failedTasks.add(taskTitle);
    }

    public void completeTask(String taskName) {
        if (tasks == null) {
            return;
        }

        tasks.removeIf(task -> task.getTaskName().equalsIgnoreCase(taskName));
    }

    public boolean isFailed(Task task)
    {
        return failedTasks.contains(task.getTaskName());
    }

    public void invalidateStreak()
    {
        streakValid = false;
        killStreak = 0;
    }

    private void incrementKillStreak() {
        killStreak++;
    }

    public void startNextAttempt() {
        bossDefeated = false;
        failedTasks.clear();
        startTime = System.currentTimeMillis();
        finishTime = 0;
    }

    public void completeAttempt()
    {
        if (bossDefeated)
        {
            return;
        }

        finishTime = System.currentTimeMillis();
        bossDefeated = true;

        incrementKillStreak();
    }

    public void end() {
        active = false;
    }

    public void heartbeat() {
        idleTicks = 0;
    }

    public boolean shouldEnd() {
        return idleTicks++ > 100;
    }

    public long getElapsedSeconds()
    {
        long endTime = bossDefeated
                ? finishTime
                : System.currentTimeMillis();

        return (endTime - startTime) / 1000;
    }
}

package com.caroadmap.api;

import com.caroadmap.dto.GetRecommendationsResponse;
import com.caroadmap.dto.TaskDTO;
import com.caroadmap.dto.TaskFromBossResponse;
import com.google.gson.Gson;
import lombok.extern.slf4j.Slf4j;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.Map;

@Singleton
@Slf4j
public class CARoadmapServer
{
    private static final String SERVER_URL =
            "https://kxin971pll.execute-api.us-east-1.amazonaws.com";

    // private static final String SERVER_URL = "http://localhost:8080";

    private static final MediaType JSON =
            MediaType.get("application/json");

    private final OkHttpClient client;
    private final Gson gson;

    @Inject
    public CARoadmapServer(OkHttpClient client, Gson gson)
    {
        log.info("Initialized CARoadmapServer");
        this.client = client;
        this.gson = gson;
    }

    public boolean storeCharacterData(
            String username,
            long accountHash,
            Map<String, ArrayList<Object>> data)
    {
        log.info("storing character data");

        Map<String, Object> dataToSend = new HashMap<>();
        dataToSend.put("username", username);
        dataToSend.put("accountHash", accountHash);
        dataToSend.put("character_details", data);

        log.info(dataToSend.toString());

        try
        {
            String jsonBody = gson.toJson(dataToSend);

            RequestBody body = RequestBody.create(JSON, jsonBody);

            Request request = new Request.Builder()
                    .url(SERVER_URL + "/characterdata")
                    .header("Content-Type", "application/json")
                    .post(body)
                    .build();

            try (Response response = client.newCall(request).execute())
            {
                return response.code() == 200;
            }
        }
        catch (Exception e)
        {
            log.error("Could not insert character data.", e);
            return false;
        }
    }

    public boolean updatePlayerBossData(
            long accountHash,
            String bossName,
            int killCount)
    {
        log.info("Updating kill count for boss {}", bossName);

        Map<String, Object> dataToSend = new HashMap<>();
        dataToSend.put("character_id", accountHash);
        dataToSend.put("boss_name", bossName);
        dataToSend.put("kc", killCount);

        try
        {
            String jsonBody = gson.toJson(dataToSend);

            RequestBody body = RequestBody.create(JSON, jsonBody);

            Request request = new Request.Builder()
                    .url(SERVER_URL + "/store_player_boss_data")
                    .header("Content-Type", "application/json")
                    .post(body)
                    .build();

            try (Response response = client.newCall(request).execute())
            {
                return response.code() == 200;
            }
        }
        catch (Exception e)
        {
            log.error("Could not insert player boss data.", e);
            return false;
        }
    }

    public boolean updatePlayerTaskStatus(
            long accountHash,
            String taskTitle)
    {
        log.info("Updating combat achievement task [{}] to done", taskTitle);

        Map<String, Object> dataToSend = new HashMap<>();
        dataToSend.put("character_id", accountHash);
        dataToSend.put("task_name", taskTitle);
        dataToSend.put("is_done", true);

        try
        {
            String jsonBody = gson.toJson(dataToSend);

            RequestBody body = RequestBody.create(JSON, jsonBody);

            Request request = new Request.Builder()
                    .url(SERVER_URL + "/store_player_task_status")
                    .header("Content-Type", "application/json")
                    .post(body)
                    .build();

            try (Response response = client.newCall(request).execute())
            {
                return response.code() == 200;
            }
        }
        catch (Exception e)
        {
            log.error("Could not insert player task status.", e);
            return false;
        }
    }

    /**
     * This function will fetch the tasks from the boss.
     *
     * @return an array of tasks from the boss inputted.
     * On error, it will return an EMPTY array.
     */
    public TaskDTO[] fetchTaskFromBoss(String boss, long accountHash)
    {
        Map<String, Object> payload = new HashMap<>();

        payload.put("character_id", accountHash);
        payload.put("boss_name", boss);

        try
        {
            String jsonBody = gson.toJson(payload);

            RequestBody body = RequestBody.create(JSON, jsonBody);

            Request request = new Request.Builder()
                    .url(SERVER_URL + "/get_tasks")
                    .header("Content-Type", "application/json")
                    .post(body)
                    .build();

            try (Response response = client.newCall(request).execute())
            {
                if (!response.isSuccessful() || response.body() == null)
                {
                    log.error(
                            "Failed to fetch task information for boss {}. Status: {}",
                            boss,
                            response.code()
                    );
                    return new TaskDTO[0];
                }

                TaskFromBossResponse parsedResponse =
                        gson.fromJson(
                                response.body().string(),
                                TaskFromBossResponse.class
                        );

                if (parsedResponse == null || parsedResponse.getTasks() == null)
                {
                    return new TaskDTO[0];
                }

                return parsedResponse.getTasks().toArray(new TaskDTO[0]);
            }
        }
        catch (Exception e)
        {
            log.error(
                    "Could not fetch task information on this boss {}",
                    boss,
                    e
            );
            return new TaskDTO[0];
        }
    }

    public GetRecommendationsResponse getRecommendations(long characterId, Integer pointsNeeded) throws Exception
    {
        try
        {
            Map<String, Object> dataToSend = new HashMap<>();
            dataToSend.put("character_id", characterId);
            // Omitted when null so the server treats it as None (hard cap of 20).
            if (pointsNeeded != null)
            {
                dataToSend.put("points_needed", pointsNeeded);
            }

            String jsonBody = gson.toJson(dataToSend);

            RequestBody body = RequestBody.create(JSON, jsonBody);

            Request request = new Request.Builder()
                    .url(SERVER_URL + "/get_recommendations")
                    .header("Content-Type", "application/json")
                    .post(body)
                    .build();

            try (Response response = client.newCall(request).execute())
            {
                if (response.body() == null)
                {
                    log.error(
                            "Failed to get recommendations. Status: {}",
                            response.code()
                    );
                    return null;
                }

                String responseBody = response.body().string();

                if (response.code() != 200)
                {
                    log.error(
                            "Failed to get recommendations. Status: {} Body: {}",
                            response.code(),
                            responseBody
                    );
                    return null;
                }

                return gson.fromJson(
                        responseBody,
                        GetRecommendationsResponse.class
                );
            }
        }
        catch (Exception e)
        {
            log.error("Error fetching recommendations from server", e);
            throw e;
        }
    }
}

package com.caroadmap.api;

import com.caroadmap.data.Boss;
import com.caroadmap.data.PlayerDataDiffUtil;
import com.caroadmap.data.Task;
import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.RuneLite;

import java.io.*;
import java.lang.reflect.Type;
import java.util.*;

@Slf4j
public class PlayerDataBatcher {
    private static final String BOSS_INFO_KEY = "boss_info";
    private static final String COMBAT_STATS_KEY = "skills";
    private static final String TASKS_KEY = "tasks";

    private final String username;
    private final long accountHash;
    private final Map<String, ArrayList<Object>> batch;
    private final CARoadmapServer server;
    private final File playerCache;


    private final Gson gson;

    public PlayerDataBatcher(String username, long accountHash ,  CARoadmapServer server, Gson gson) {
        this.gson = gson.newBuilder().setPrettyPrinting().create();
        this.username = username;
        this.server = server;
        this.accountHash = accountHash;

        File pluginDir = new File(RuneLite.RUNELITE_DIR, "caroadmap");
        this.playerCache = new File(pluginDir, String.format("player_cache_%d.json", accountHash));

        this.batch = new HashMap<>();
        batch.put(BOSS_INFO_KEY, new ArrayList<>());
        batch.put(COMBAT_STATS_KEY, new ArrayList<>());
        batch.put(TASKS_KEY, new ArrayList<>());

    }

    public boolean addBossToBatch(Boss boss) {
        try {
            batch.get(BOSS_INFO_KEY).add(boss.formatBoss());
            return true;
        } catch (Exception e) {
            log.error("Could not add boss info to batch: ", e);
            return false;
        }
    }

    public boolean addSkillToBatch(String skillName, int level) {
        Map<String, Object> skillMap = new HashMap<>();
        skillMap.put("skill_name", skillName);
        skillMap.put("level", level);

        try {
            batch.get(COMBAT_STATS_KEY).add(skillMap);
            return true;
        } catch (Exception e) {
            log.error("Could not add skill info to batch: ", e);
            return false;
        }
    }

    public boolean addTaskToBatch(Task task) {
        Map<String, Object> userTaskObj = new HashMap<>();
        userTaskObj.put("Done", task.isDone());
        userTaskObj.put("task_name", task.getTaskName());

        try {
            batch.get(TASKS_KEY).add(userTaskObj);
            return true;
        } catch (Exception e) {
            log.error("Could not add task info to batch: ", e);
            return false;
        }
    }

    public Map<String, ArrayList<Object>> loadPlayerCache() {
        if (!playerCache.exists()) {
            return null;
        }
        try (Reader reader = new FileReader(playerCache)) {
            Type type = new TypeToken<Map<String, ArrayList<Object>>>() {}.getType();
            return gson.fromJson(reader, type);
        } catch (Exception e) {
            log.error("Could not read player cache from file: ", e);
            return null;
        }
    }

    public boolean writeToLocalCache(Map<String, ArrayList<Object>> batchCopy) {
        try (Writer writer = new FileWriter(playerCache)) {
            gson.toJson(batchCopy, writer);
            return true;
        } catch (IOException e) {
            log.error("Failed to write updated player cache to file: ", e);
            return false;
        }
    }

    public boolean sendData() {
        Map<String, ArrayList<Object>> localCache = loadPlayerCache();
        boolean hasUpdates = false;

        // Deep copy batch by serializing and deserializing with Gson
        String batchJson = gson.toJson(batch);
        Type type = new TypeToken<Map<String, ArrayList<Object>>>() {}.getType();
        Map<String, ArrayList<Object>> batchCopy = gson.fromJson(batchJson, type);

        if (localCache == null) {
            log.warn("No player cache found, uploading full batch.");
            if (server.storeCharacterData(username, accountHash, batch)) {
                writeToLocalCache(batchCopy);
                return true;
            }
            else {
                log.error("Could not store character data.");
                return false;
            }
        }


        // Filter out unchanged data by comparing to cache
        for (Map.Entry<String, ArrayList<Object>> entry : batch.entrySet()) {
            String key = entry.getKey();
            ArrayList<Object> newData = entry.getValue();
            ArrayList<Object> cachedData = localCache.getOrDefault(key, new ArrayList<>());

            List<Object> filteredData = PlayerDataDiffUtil.filterByKey(key, newData, cachedData);

            if (!filteredData.isEmpty()) {
                hasUpdates = true;
            }

            batch.put(key, new ArrayList<>(filteredData));
        }

        log.info("sending data");

        if (!hasUpdates) {
            log.info("No player data changes detected; skipping upload.");
            return true;
        }

        if (server.storeCharacterData(username, accountHash, batch)) {
            writeToLocalCache(batchCopy);
            return true;
        }
        else {
            log.error("Something went wrong.");
        }

        return false;
    }
}

package com.caroadmap.api;

import com.caroadmap.data.Boss;
import com.caroadmap.dto.EhbResponse;
import com.caroadmap.ui.BossNameUtil;
import com.google.gson.Gson;
import lombok.extern.slf4j.Slf4j;
import okhttp3.HttpUrl;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;

import javax.inject.Inject;
import java.io.IOException;
import java.util.ArrayList;
import java.util.List;

@Slf4j
public class WiseOldMan
{
    private static final String WISE_OLD_MAN_API = "https://api.wiseoldman.net/v2/players/";

    private final OkHttpClient client;
    private final Gson gson;

    @Inject
    public WiseOldMan(OkHttpClient client, Gson gson)
    {
        this.client = client;
        this.gson = gson;
    }

    /**
     * Fetches boss info from Wise Old Man API.
     * Returns an empty array if any error occurs or data is not found.
     */
    public Boss[] fetchBossInfo(String displayName)
    {
        HttpUrl url = HttpUrl.parse(WISE_OLD_MAN_API + displayName);

        if (url == null)
        {
            log.warn("Failed to create Wise Old Man URL for user '{}'", displayName);
            return new Boss[0];
        }

        Request request = new Request.Builder()
                .url(url)
                .get()
                .build();

        try (Response response = client.newCall(request).execute())
        {
            if (!response.isSuccessful())
            {
                log.warn(
                        "Received non-success response from Wise Old Man API for user '{}': {}",
                        displayName,
                        response.code()
                );
                return new Boss[0];
            }

            if (response.body() == null)
            {
                log.warn("Wise Old Man API returned an empty response for user '{}'", displayName);
                return new Boss[0];
            }

            EhbResponse ehbResponse = gson.fromJson(
                    response.body().string(),
                    EhbResponse.class
            );

            if (ehbResponse == null
                    || ehbResponse.latestSnapshot == null
                    || ehbResponse.latestSnapshot.data == null
                    || ehbResponse.latestSnapshot.data.bosses == null)
            {
                log.warn("Wise Old Man API returned no boss data for user '{}'", displayName);
                return new Boss[0];
            }

            List<Boss> bossList = new ArrayList<>();

            ehbResponse.latestSnapshot.data.bosses.values().forEach(boss ->
            {
                String normalized = BossNameUtil.normalizeForDatabase(boss.metric);
                bossList.add(new Boss(normalized, boss.kills, boss.ehb));
            });

            return bossList.toArray(new Boss[0]);
        }
        catch (IOException e)
        {
            log.error(
                    "Failed to fetch data from Wise Old Man API for user '{}'",
                    displayName,
                    e
            );
            return new Boss[0];
        }
        catch (Exception e)
        {
            log.error(
                    "Failed to parse Wise Old Man API response for user '{}'",
                    displayName,
                    e
            );
            return new Boss[0];
        }
    }
}

